import fs from 'node:fs';
import vm from 'node:vm';
import {webcrypto} from 'node:crypto';

const read=p=>fs.readFileSync(p,'utf8');
const write=(p,s)=>fs.writeFileSync(p,s);
const must=(ok,msg)=>{if(!ok)throw new Error(msg);};
const replaceOnce=(s,a,b,label)=>{must(s.includes(a),`Missing replacement target: ${label||a.slice(0,80)}`);return s.replace(a,b);};
const replaceRe=(s,re,b,label)=>{must(re.test(s),`Missing regex replacement target: ${label||re}`);return s.replace(re,b);};
const clone=v=>JSON.parse(JSON.stringify(v));

const originalWorkbook=read('workbook.js');
const originalSchema=read('workflow-schema.js');
const context={console,crypto:webcrypto,TextEncoder,TextDecoder,dispatchEvent(){},Event:class Event{constructor(type){this.type=type;}}};
context.globalThis=context;
vm.createContext(context);
vm.runInContext(originalWorkbook,context,{filename:'workbook.js'});
vm.runInContext(originalSchema,context,{filename:'workflow-schema.js'});
const oldCore=context.closedLoopCore;
const oldSchema=context.closedLoopWorkflowSchema;

const stageOwnership={};
for(const stage of oldCore.STAGES){
  const partition={human:[],humanDecision:[],agent:[],application:[]};
  for(const name of stage.fields){
    const producer=oldSchema.STAGE_FIELDS[stage.number][name].producer;
    const key=producer==='HUMAN'?'human':producer==='HUMAN_DECISION'?'humanDecision':producer==='AGENT'?'agent':'application';
    partition[key].push(name);
  }
  stageOwnership[stage.number]=partition;
}
const recordOwnership={};
const lifecycle=new Set(['STATUS','ACTIVE_RETIRED_STATE','AUTHORIZATION','VERSION','CREATED_AT','UPDATED_AT','CURRENT_STATE']);
for(const [collection,definition] of Object.entries(oldSchema.RECORD_SCHEMAS)){
  const partition={human:[],humanDecision:[],agent:[],application:[]};
  for(const name of definition.fields){
    let producer=definition.fieldDefinitions[name].producer;
    if(lifecycle.has(name))producer='APPLICATION';
    const key=producer==='HUMAN'?'human':producer==='HUMAN_DECISION'?'humanDecision':producer==='AGENT'?'agent':'application';
    partition[key].push(name);
  }
  recordOwnership[collection]=partition;
}

const stageOwnershipLiteral=JSON.stringify(stageOwnership,null,2);
const recordOwnershipLiteral=JSON.stringify(recordOwnership,null,2);

