workbook=replaceOnce(workbook,"const SCHEMA='human-project/30';",`const WORKFLOW_ID='mobile-closed-loop/30';\nconst PROJECT_SCHEMA='closed-loop-project/2';\nconst STAGE_COUNT=30;\nconst SCHEMA=PROJECT_SCHEMA;`,'workbook identity constants');
