ingestion=replaceOnce(ingestion,"  const priorDuplicate=safe(project.projectData.rawResponses).find(record=>record.status!=='PRESERVED'&&record.sha256===rawSha256", "  const canonicalEnvelopeSha256=hash.canonicalEnvelopeSha256(envelope);\n  const priorSemantic=safe(project.projectData.rawResponses).find(record=>record.canonicalEnvelopeSha256===canonicalEnvelopeSha256&&Number(record.stage)===stageNumber&&(record.promptInstructionId||'')===(promptRecord?.instructionId||promptRecord?.promptId||''));if(priorSemantic)issues.push(issue('DUPLICATE_RESPONSE','/',`This semantic response already exists as ${priorSemantic.rawResponseId}.`));\n  const priorDuplicate=safe(project.projectData.rawResponses).find(record=>record.status!=='PRESERVED'&&record.sha256===rawSha256",'semantic duplicate');
ingestion=ingestion.replace('    temporaryEvidenceIndex:evidenceIndex','    temporaryEvidenceIndex:evidenceIndex,canonicalEnvelopeSha256');
ingestion=ingestion.replace("promptSha256:promptRecord.sha256||promptRecord.bodySha256", "bodySha256:promptRecord.bodySha256||promptRecord.sha256,contractSha256:promptRecord.contractSha256,contextSignature:promptRecord.contextSignature,scopeSha256:promptRecord.scopeSha256");
ingestion=ingestion.replace("const rawSha256=hash.sha256Text(rawText);", "const rawSha256=hash.rawResponseSha256(rawText);");
ingestion=ingestion.replace("files:clone(files),status:'PRESERVED'", "files:clone(files),status:'PRESERVED',projectRevision:Number(next.revision||0)");
ingestion=ingestion.replace("else validation=validateEnvelope(next,envelope,{stage:stageNumber,promptRecord:prompt,rawSha256});", "else validation=validateEnvelope(next,envelope,{stage:stageNumber,promptRecord:prompt,rawSha256});\n  if(envelope)rawRecord.canonicalEnvelopeSha256=hash.canonicalEnvelopeSha256(envelope);");
ingestion=ingestion.replace("version:'closed-loop-response-ingestion/1'", "version:'closed-loop-response-ingestion/2'");
ingestion=ingestion.replace('strictParse,validateEnvelope,planProposal,prepare,commit,reject,answerHumanInput', 'strictParse,scanJsonAmbiguity,validateValue,validateEnvelope,planProposal,prepare,commit,reject,answerHumanInput');
write('response-ingestion.js',ingestion);

// Verification: assert the new structural contract and adapt old response fixtures mechanically.
let verify=read('verify.mjs');
verify += `\n// Practical-100 schema/ownership contract.\nassert(core.PROJECT_SCHEMA==='closed-loop-project/2'&&core.WORKFLOW_ID==='mobile-closed-loop/30'&&core.STAGE_COUNT===30,'Project/workflow identities must be separated.');\nassert(schema.RESPONSE_SCHEMA==='closed-loop-stage-response/2','Response schema /2 is required.');\nfor(const stage of core.STAGES){const p=stage.ownership;const union=[...p.human,...p.humanDecision,...p.agent,...p.application];assert(union.length===stage.fields.length&&new Set(union).size===stage.fields.length&&stage.fields.every(f=>union.includes(f)),\`Stage \${stage.number} ownership must be a complete disjoint partition.\`);for(const def of Object.values(schema.STAGE_FIELDS[stage.number])){assert(schema.VALUE_TYPES.includes(def.valueType),'Every stage field needs a valueType.');assert(Array.isArray(def.enumValues),'Every stage field needs enumValues.');assert(Object.hasOwn(def,'nullable')&&Object.hasOwn(def,'normalizerKey'),'Every stage field needs nullability and normalizer metadata.');}}\nfor(const [name,def] of Object.entries(schema.RECORD_SCHEMAS)){const p=def.ownership;const union=[...p.human,...p.humanDecision,...p.agent,...p.application];assert(union.length===def.fields.length&&new Set(union).size===def.fields.length&&def.fields.every(f=>union.includes(f)),\`\${name} ownership must be a complete disjoint partition.\`);}\n`;
write('verify.mjs',verify);

// Update ingestion verifier helpers to the /2 prompt identity when recognizable.
let vi=read('verify-ingestion.mjs');
vi=vi.replaceAll("closed-loop-stage-response/1","closed-loop-stage-response/2");
vi=vi.replace(/promptIdentity:\{instructionId:prompt\.instructionId,sha256:prompt\.sha256\}/g,"operation:prompt.operation,promptIdentity:{instructionId:prompt.instructionId,bodySha256:prompt.bodySha256,contractSha256:prompt.contractSha256,contextSignature:prompt.contextSignature},scope:prompt.scope");
vi=vi.replace(/promptIdentity:\{instructionId:promptRecord\.instructionId,sha256:promptRecord\.sha256\}/g,"operation:promptRecord.operation,promptIdentity:{instructionId:promptRecord.instructionId,bodySha256:promptRecord.bodySha256,contractSha256:promptRecord.contractSha256,contextSignature:promptRecord.contextSignature},scope:promptRecord.scope");
write('verify-ingestion.mjs',vi);

console.log('PR2 transformation complete');
